fn main() {
    // `valeur` est allouée sur le tas, `b` est un pointeur sur la pile
    let b = Box::new(5);

    // `*b` déréférence la Box pour atteindre la valeur pointée
    println!("b vaut {}", *b); // affiche : b vaut 5

    // On peut souvent omettre le `*` : Rust déréférence automatiquement
    let somme = *b + 10;
    println!("somme = {somme}"); // affiche : somme = 15
} // ici `b` sort du scope : la mémoire du tas est libérée automatiquement

// Chaque maillon contient une valeur et, éventuellement, la suite.
// Sans `Box`, `List` se contiendrait elle-même : taille infinie, refus du compilateur.
enum List {
    Cons(i32, Box<List>), // la suite est derrière un pointeur de taille fixe
    Nil,                  // fin de la liste
}

use List::{Cons, Nil};

fn main() {
    // Construit la liste 1 -> 2 -> 3 -> Nil
    let liste = Cons(1, Box::new(Cons(2, Box::new(Cons(3, Box::new(Nil))))));

    // Parcours en suivant les pointeurs
    let mut courant = &liste;
    while let Cons(valeur, suite) = courant {
        println!("valeur = {valeur}");
        courant = suite; // on avance sur le maillon suivant
    }
}

use std::rc::Rc;

fn main() {
    let origine = Rc::new(String::from("données partagées"));
    println!("compteur = {}", Rc::strong_count(&origine)); // 1

    let a = Rc::clone(&origine); // incrémente le compteur, ne copie pas la String
    println!("compteur = {}", Rc::strong_count(&origine)); // 2

    {
        let b = Rc::clone(&origine);
        println!("compteur = {}", Rc::strong_count(&origine)); // 3
    } // `b` sort du scope : le compteur redescend

    println!("compteur = {}", Rc::strong_count(&origine)); // 2
    println!("a lit : {a}"); // tous pointent vers la même donnée
}

use std::cell::RefCell;

fn main() {
    // `compteur` n'est pas déclaré `mut`, pourtant on va modifier son contenu
    let compteur = RefCell::new(0);

    *compteur.borrow_mut() += 1; // emprunt mutable, vérifié à l'exécution
    *compteur.borrow_mut() += 1; // l'emprunt précédent est déjà relâché, donc OK

    println!("valeur = {}", compteur.borrow()); // emprunt en lecture : affiche 2

    // Piège : garder deux emprunts mutables actifs en même temps
    // let a = compteur.borrow_mut();
    // let b = compteur.borrow_mut(); // PANIC au runtime : already borrowed
}

